type Order = { type: string; payload: any };
function handleOrder(order: Order) {
  switch (order.type) {
    case 'create': return createOrder(order.payload);
    case 'update': return updateOrder(order.payload);
    case 'cancel': return cancelOrder(order.payload);
    default: throw new Error('Unknown');
  }
}

type Event = { kind: 'create' | 'update' | 'delete'; data: any };
function dispatch(e: Event) {
  switch (e.kind) {
    case 'create': return handleCreate(e.data);
    case 'update': return handleUpdate(e.data);
    case 'delete': return handleDelete(e.data);
  }
}

/* Version A */
class OrderProcessorA {
  process(order: any) {
    switch (order.type) {
      case 'simple': return handleSimple(order);
      case 'complex': return handleComplex(order);
      case 'premium': return handlePremium(order);
    }
  }
}

/* Version B */
interface OrderHandler { canHandle(o:any): boolean; handle(o:any): any }
const handlers: OrderHandler[] = [];
function processOrderB(order: any) {
  const h = handlers.find(x => x.canHandle(order));
  return h!.handle(order);
}
